const e={title:"TripReel - Travel Map Animation App | Trip Highlight Video Maker",description:"Create stunning trip highlight videos and travel recap videos with animated maps. Free travel map animation app with journey route animator and 3D globe route mapping. Turn your photos into beautiful trip animation videos automatically. Privacy-first animated travel map app, works offline.",keywords:"travel map animation app, trip highlight video app, trip recap video app, journey route animator app, travel recap app, animated travel map app, travel route animation app, map journey video app, travel story maker app, trip animation app, travel video maker app, flight animation app, automatic travel video, flight path animation, journey animation app, globe animation, photo to video app, trip highlights, free travel app, offline video maker, privacy travel app, camera roll video"},t={logoAlt:"TripReel Logo",appName:"TripReel",howItWorks:"How It Works",video:"Video",features:"Features",theApp:"The app"},a={badge:"Turn Photos Into Travel Stories",title1:"Your Camera Roll,",title2:"Fully Tapped",description:"TripReel is the ultimate travel map animation app that automatically creates beautiful trip highlight videos and travel recap videos from your photos' locations. Watch your journeys come alive with our journey route animator featuring stunning animated route maps and flight paths across a 3D globe, all while keeping your data private and secure.",secure:"100% Secure",worksOffline:"Works Offline",globeAlt:"TripReel Globe Animation"},o={title:"How It Works",subtitle:"Three simple steps to create your perfect travel video",step1:{title:"Allow Photo Access",description:"Grant TripReel access to your photo library. The app only reads location metadata, nothing else."},step2:{title:"Automatic Trip Detection",description:"TripReel analyzes location metadata and intelligently finds your trips based on dates and locations."},step3:{title:"Generate Your Video",description:"Watch as your journey unfolds with our journey route animator on a beautiful globe animation, creating stunning trip highlight videos ready to share on social media."}},i={title:"See The Magic Happen",subtitle:"Watch how our travel map animation app transforms your photo library into stunning trip highlight videos and travel recap videos with animated route maps",caption:"This is what your final trip animation video can look like with our journey route animator app"},r={title:"Everything You Need",subtitle:"Powerful features designed for modern travelers",twoTap:{title:"Two-Tap Travel Videos",description:"Create stunning trip highlight videos and travel recap videos from your photo library in just two taps with our travel video maker app. No editing required."},smartTrip:{title:"Smart Trip Detection",description:"The travel recap app automatically finds and groups your trips by analyzing dates and location metadata from your photos to create perfect trip highlight videos."},globe:{title:"Beautiful Globe Animation",description:"Watch your journey come to life with our journey route animator featuring a stunning 3D globe showing your animated travel routes and flight paths across the world in beautiful map journey videos."},privacy:{title:"Privacy First",description:"The travel map animation app processes everything on your device. Your photos never leave your phone. Create trip animation videos completely offline in airplane mode."},customStyles:{title:"Custom Styles",description:"Choose from multiple earth styles and customizations for your trip animation videos to match your aesthetic and make each animated travel map video unique."},manualControl:{title:"Manual Control",description:"The journey route animator app lets you manually add entirely new trips and customize your travel route animation if location services weren't enabled on your device."}},n={title:"Creative Video Ideas",subtitle:"Get inspired with what you can create using TripReel, your travel story maker app. From quick weekend getaways to year-long adventures, create stunning trip highlight videos and travel recap videos for every journey.",description:"Whether you're creating a travel map animation, documenting a flight route with our journey route animator, or making a year-end travel recap app video, TripReel makes it effortless to transform your memories into shareable trip animation videos.",ideas:{yearRecap:{title:"2025 Travel Recap",description:"Create your 2025 yearly travel recap video automatically with our trip highlight video app"},europeRoadTrip:{title:"Europe Road Trip",description:"Showcase your European adventure with our travel map animation app and animated route maps"},southeastAsia:{title:"Southeast Asia Journey",description:"Visualize your backpacking route across multiple countries with our journey route animator app"},japanRail:{title:"Japan Rail Journey",description:"Create map journey videos of your train routes across Japan with animated travel maps"},crossCountry:{title:"Cross-Country USA",description:"Turn your American road trip into an epic travel route animation video with our trip animation app"},islandHopping:{title:"Island Hopping",description:"Show your island-to-island travels with stunning 3D animations using our travel story maker app"},worldTour:{title:"World Tour Montage",description:"Combine multiple trips into one amazing global journey video with our animated travel map app"},travelPlans:{title:"2026 Travel Plans",description:"Visualize and plan your exciting 2026 travel adventures with our journey route animator"},lifetimeTravel:{title:"Lifetime Travel Story",description:"Create a trip recap video showcasing all your life-long travels with our travel recap app"},regionalExplorer:{title:"Regional Explorer",description:"Chart your adventures across states, provinces, and regions with our travel map animation app"},festivalCircuit:{title:"Festival Circuit",description:"Map out your music festival and event journey with animated travel route videos"},bikeRoutes:{title:"My City Breaks",description:"Showcase all your city escapades with beautiful map journey videos"}}},s={title:"The app",subtitle:"Available now on App Store",alt1:"Travel Map Animation App - Create trip highlight videos automatically in seconds",alt2:"Journey Route Animator - Uses your photos' location metadata for travel recap videos",alt3:"Trip Detection - Automatically groups your travels for animated travel map videos",alt4:"Beautiful Earth Videos - Globe animation of your journey with our trip animation app",alt5:"Custom Styles - Personalize your travel route animation videos with multiple earth styles"},l={comingSoon:"Coming Soon",androidTitle:"Android App Coming Soon!",androidMessage:'The Android version is not yet available but will be soon. Message me at <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> and I\'ll let you know when it\'s ready!',gotIt:"Got it!"},p={title:"Frequently Asked Questions",subtitle:"Everything you need to know about TripReel",q1:{question:"Can I use this travel map animation app fully offline in airplane mode?",answer:"Yes! For premium users, the trip highlight video app can be used completely offline in airplane mode with no limitations. For non-premium users, some features are ad-supported which might require temporarily enabling internet, but premium users can create travel recap videos fully offline with no ads."},q2:{question:"How do I remove the watermark from my trip animation videos?",answer:"Many people ask what travel video maker app was used to create these animated travel map videos. After upgrading to premium, you have the option to add a smaller version of the watermark (with just the app name) or completely remove it from your trip highlight videos if you wish."},q3:{question:"Is my photo data safe and private in this journey route animator app?",answer:"Absolutely! The travel map animation app only reads location metadata from your photos - we never access, store, or transmit the actual photo content. All trip animation video processing happens locally on your device, and no data ever leaves your phone. You can verify this by creating travel recap videos in airplane mode - it works perfectly offline!"},q4:{question:"What if my photos don't have location data for the travel route animation?",answer:"No problem! If location services weren't enabled when you took your photos, the travel story maker app lets you manually create trips and add locations yourself. The journey route animator gives you full control to customize your travel timeline and create beautiful animated travel map videos even without GPS data."},q5:{question:"How does this trip recap video app detect my trips automatically?",answer:"The travel map animation app analyzes the location metadata and timestamps from your photos to intelligently identify when and where you traveled. It groups nearby locations and dates together to automatically detect your trips and create stunning trip highlight videos without any manual work required."},q6:{question:"Can I customize the appearance of my trip highlight videos?",answer:"Yes! Our trip animation app lets you choose from multiple earth styles and customize various aspects of your animated travel map videos to match your personal aesthetic. Premium users get access to additional route animation styles, map themes, and flight path options."},q7:{question:"Do I need to create an account to use this travel video maker app?",answer:"No account required! The trip animation app works immediately after download. There's no registration, no login, and no personal information needed. Just download the travel map animation app and start creating your animated travel route videos right away."},q8:{question:"Why is a location missing from my animated travel map video?",answer:"The journey route animator app can only work with available data, so you need at least a couple of photos in that location with GPS data. Make sure you had location services enabled when you were there. Sometimes low GPS reception can cause wrong location data. If your location still doesn't show up in your trip highlight video, you can manually add that location from the Trips Overview > Edit button. Please use Contact to report the issue."},q9:{question:"Where can I share my trip recap videos and travel route animations?",answer:"You can share your trip animation videos on all social platforms! Our travel map animation app allows different aspect ratios (vertical, widescreen, cinema, square) for your animated travel map videos to better suit each platform - perfect for Instagram, TikTok, YouTube, Facebook, and more."},q10:{question:"Where can I report a bug?",answer:"Just contact me directly at marian@qod.ee, briefly explaining what the issue is."}},u={title:"Email Support",description:"If you have any feedback or encounter any issues, please feel free to contact me directly at this email and I'll personally read and handle your request as fast as possible. Thanks for using the app!",close:"Close"},d={default:{title:"🍪 Cookies",message:"We use cookies on the TripReel site to enhance your experience. No personal data collected.",accept:"Accept",decline:"Decline",details:"Details"},theme:{title:"🍪 Cookies",message:"🌙 To save your theme preference, you need to accept essential cookies on the TripReel site. Without them, your theme choice cannot be saved.",accept:"Accept",decline:"Decline",details:"Details"}},m={privacy:"App Privacy Policy",cookies:"Site Cookie Policy",contact:"Contact",cookiePreferences:"Cookie Preferences",madeWith:"Made with",forTravelers:"for travelers worldwide",copyright:"© {{year}} TripReel."},c={title:"Ready to Share Your Journey?",description:"Download TripReel today and transform your camera roll into beautiful trip highlight videos with our animated travel map app featuring journey route animator and travel route animation. Your adventures deserve to be celebrated with stunning travel recap videos.",features:"Free to download • Fast & Convenient • Privacy guaranteed"},h={title:"About TripReel",subtitle:"Professional trip highlight video maker and journey route animator app",howItWorks:{title:"How Our Travel Recap App Works",description:"The trip animation app uses intelligent algorithms to scan your photos' GPS data and automatically detect your trips. The journey route animator then creates smooth, cinematic travel route animations showing your path across cities, countries, and continents. Whether you're creating a quick weekend trip highlight video or a year-long travel recap video, the animated travel map app makes it effortless."},customization:{title:"Extensive Customization for Your Trip Animation Videos",description:"The travel story maker app offers professional-level customization options to make your animated travel map videos truly unique:",features:{videoQuality:"Choose between 30 FPS, 60 FPS, or premium 90 FPS for silky-smooth travel route animations in your trip highlight videos",bitrate:"Adjust video quality (bitrate) from normal to high for crystal-clear map journey videos without visual artifacts",earthStyles:"Select from multiple stunning earth styles including Realistic, Night Lights, Day Map, and Satellite views for your animated travel map videos",borders:"Toggle country borders on your journey route animator with customizable colors and thickness for enhanced geography visualization",aspectRatios:"Create trip animation videos in Vertical (9:16), Widescreen (16:9), Cinema (2.35:1), or Square (1:1) formats perfect for Instagram, TikTok, YouTube, and other social platforms",tripSpeed:"Control the journey route animator speed between locations (up to 3500 km/s) to create dynamic or relaxed travel recap videos",pauseDuration:"Adjust pause duration at each location (0.5-5 seconds) to highlight important destinations in your trip highlight videos",locationLabels:"Display City, Region, and/or Country labels on your animated travel map videos to provide context for your journey",pathDisplay:"Toggle whether to show all past trip paths or just the current trip in your travel route animation"}}},y={meta:e,header:t,hero:a,howItWorks:o,videoSection:i,features:r,videoIdeas:n,screenshots:s,appStore:l,faq:p,contact:u,cookieBanner:d,footer:m,cta:c,about:h};export{h as about,l as appStore,u as contact,d as cookieBanner,c as cta,y as default,p as faq,r as features,m as footer,t as header,a as hero,o as howItWorks,e as meta,s as screenshots,n as videoIdeas,i as videoSection};
